// Minimal stand-ins for Home Assistant's <ha-card> and <ha-icon> so the cards render outside HA.
// ha-icon draws Material Design Icons from ICONS (generated by tools/gen-icons.mjs into icons.js).
customElements.define("ha-card", class extends HTMLElement {});
customElements.define("ha-icon", class extends HTMLElement {
  static get observedAttributes() { return ["icon"]; }
  attributeChangedCallback() { this.r(); }
  connectedCallback() { this.r(); }
  r() {
    const n = (this.getAttribute("icon") || "").replace("mdi:", "");
    const s = getComputedStyle(this).getPropertyValue("--mdc-icon-size") || "24px";
    this.style.display = "inline-flex";
    this.innerHTML = `<svg viewBox="0 0 24 24" width="${s}" height="${s}"><path fill="currentColor" d="${(window.ICONS || {})[n] || ""}"/></svg>`;
  }
});
